package com.dreamcore.workspace;
import com.dreamcore.workspace.conversation.*;
import com.dreamcore.workspace.identity.IdentityException;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class BriefingEditorialQualityIntegrationTest extends DatasetCalculationFixture {
 ConversationService.Job start(){var j=task(null,"AUTHORIZED_LIBRARY");agents.openExecution(j.id(),j.token(),new AgentTaskService.ExecutionOpen("1.5",List.of("task_context","deliver_briefing")));agents.toolReceipt(j.id(),j.token(),new AgentTaskService.ToolReceipt(1,"task_context","STARTED"));call(j,request("dataset_search",null,null,0));agents.toolReceipt(j.id(),j.token(),new AgentTaskService.ToolReceipt(1,"task_context","succeeded"));agents.toolReceipt(j.id(),j.token(),new AgentTaskService.ToolReceipt(2,"deliver_briefing","STARTED"));UUID p=UUID.randomUUID();db.update("INSERT INTO briefing_generation_policies(id,tenant_id,owner_id,workspace_id) VALUES (?,?,?,?)",p,tenant,owner,space);db.update("INSERT INTO briefing_generation_batches(id,tenant_id,owner_id,workspace_id,policy_id,policy_epoch,trigger_kind,status,task_id) VALUES (?,?,?,?,?,1,'MANUAL','RUNNING',?)",UUID.randomUUID(),tenant,owner,space,p,j.id());return j;}
 BriefingContentService.Request card(String title,String summary){return new BriefingContentService.Request(null,title,summary,List.of("本次查看的部分记录显示已取消，不能据此认定已经退款。","建议核实对应订单和退款记录，确认业务处理是否完成。"),"INSIGHT");}
 @Test void automaticDeliveryRejectsTechnicalInventoryBeforePersistingCard(){var j=start();for(var r:List.of(card("收款明细数据集结构概览","收款数据包含三个字段，需要进行进一步分析。"),card("部分记录标记已取消","部分记录显示 canceled，仍需进一步核实业务状态。"),card("收款记录中定金占比高","收款记录多数为定金，需要关注订单转化。"))){var ex=assertThrows(IdentityException.class,()->agents.deliverBriefing(j.id(),j.token(),r));assertEquals(422,ex.status);}assertEquals(0,db.queryForObject("SELECT count(*) FROM conversation_artifacts WHERE task_id=? AND filename LIKE 'briefing-%'",Integer.class,j.id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM briefing_content_keys WHERE task_id=?",Integer.class,j.id()));}
 @Test void supportedIndividualObservationPassesAndNoCalculationIsClaimed(){var j=start();var r=agents.deliverBriefing(j.id(),j.token(),card("部分收款记录标记已取消","部分收款记录标记为已取消，是否已退款仍需核实。"));assertNotNull(r);assertEquals(1,db.queryForObject("SELECT count(*) FROM conversation_artifacts WHERE task_id=? AND filename LIKE 'briefing-%'",Integer.class,j.id()));}
 @Test void futureMeasurementSuggestionIsNotMisclassifiedAsStatisticalClaim(){var r=card("部分收款记录需要核实","建议统计定金转化比例，目前不能判断是否增长。");assertDoesNotThrow(()->BriefingEditorialQuality.validate(r,true,true,false));assertDoesNotThrow(()->BriefingEditorialQuality.validate(card("业务报道显示同比增长","有依据的公开报道显示同比增长，需要说明统计范围。"),true,false,false));assertThrows(IdentityException.class,()->BriefingEditorialQuality.validate(card("已核实金额变化","多数记录为定金，存在需要进一步核实的业务问题。"),true,true,true));}
}
